const messages = $input.all();

function reparerEncodage(s) {
  if (!s || typeof s !== "string") return s;
  try {
    const reparee = Buffer.from(s, "latin1").toString("utf8");
    const scoreOriginal = (s.match(/Ã|â€/g) || []).length;
    const scoreRepare = (reparee.match(/Ã|â€|\uFFFD/g) || []).length;
    return scoreRepare < scoreOriginal ? reparee : s;
  } catch (e) { return s; }
}
function extraireExpediteur(from) {
  if (!from) return { email: "", nom: "" };
  if (typeof from === "string") {
    const m = from.match(/^(.*?)\s*<([^<>]+)>\s*$/);
    if (m) return { email: m[2].trim().toLowerCase(), nom: m[1].replace(/^"|"$/g, "").trim() };
    return { email: from.trim().toLowerCase(), nom: "" };
  }
  const v = Array.isArray(from.value) && from.value[0] ? from.value[0] : null;
  if (v) return { email: (v.address || "").toLowerCase(), nom: v.name || "" };
  if (from.address) return { email: from.address.toLowerCase(), nom: from.name || "" };
  return { email: String(from.text || "").toLowerCase(), nom: "" };
}
function destinataire(msg) {
  // En-têtes d'acheminement d'abord : ce sont ceux que le serveur a réellement utilisés.
  const h = (msg.headers || (msg.metadata || {}).headers || msg.metadata || {});
  const brut = h["delivered-to"] || h["Delivered-To"] || h["x-original-to"] || h["X-Original-To"] || msg.to || "";
  const v = typeof brut === "object" ? (brut.text || ((brut.value || [])[0] || {}).address || "") : String(brut);
  const m = String(v).match(/<([^<>]+)>/);
  return (m ? m[1] : String(v).split(",")[0]).trim().toLowerCase();
}
function texte(v){ if(!v) return ""; if(typeof v==="string") return reparerEncodage(v); if(typeof v==="object"&&v.text) return reparerEncodage(v.text); return String(v); }

const sortie = [];
for (const m of messages) {
  const msg = m.json;
  const exp = extraireExpediteur(msg.from);
  const sujet = texte(msg.subject);
  // Anti-boucle : ignorer nos propres notifications
if (msg.init_curseur || msg.rien_de_nouveau || msg.erreur_polling) continue;
if (exp.email === "nexorasolutions.france@gmail.com" || /^Nexora\s*[—–-]/.test(sujet.trim())) continue;
  const corps = texte(msg.text) || texte(msg.textPlain) || texte(msg.snippet) || "";
  sortie.push({ json: {
    nom: exp.nom, telephone: "", email: exp.email,
    message: (sujet ? sujet + "\n" : "") + corps.trim(),
    source: "gmail", canal: "email", source_id: msg.id || null,
    garage_id: msg.garage_id || null,
    destinataire: destinataire(msg),
  }});
}
return sortie;

const body = $input.first().json.body || $input.first().json;
return [{ json: {
  nom: body.nom || "",
  telephone: body.telephone || "",
  email: (body.email || "").toLowerCase().trim(),
  message: body.message || "",
  source: "site",
  canal: "site",
  source_id: null,
  garage_id: body.garage_id || null,
} }];

const body = $input.first().json.body || $input.first().json;
return [{ json: {
  nom: body.ProfileName || "",
  telephone: (body.From || "").replace("whatsapp:", "").trim(),
  email: "",
  message: body.Body || "",
  source: "whatsapp",
  canal: "whatsapp",
  source_id: body.MessageSid || null,
  numero_whatsapp: (body.To || "").replace("whatsapp:", "").trim(),
} }];

const j = $input.first().json || {};
if (!j.source) return [];  // retour de boucle (résultat SMTP, etc.) : ce n'est pas un message
return [{ json: j }];

const nouveau = $('Point d\'entrée unifié').item.json;
const clients = $input.all().map(i => i.json);

const emailN = (nouveau.email || "").toLowerCase().trim();
const telN = (nouveau.telephone || "").trim();

let match = null;
if (emailN) match = clients.find(c => (c.email || "").toLowerCase().trim() === emailN);
if (!match && telN) match = clients.find(c => (c.telephone || "").trim() === telN);

return [{ json: { ...nouveau, client_existant_id: match ? match.id : null } }];

const nouveau = $('Identifier le client existant (email ou téléphone)').item.json;
const demandesPrecedentes = $input.all().map(i => i.json);
const DEUX_JOURS_MS = 48 * 60 * 60 * 1000;
const maintenant = Date.now();
const contexte = demandesPrecedentes.filter(d => d.created_at && (maintenant - new Date(d.created_at).getTime()) < DEUX_JOURS_MS).sort((a, b) => new Date(b.created_at) - new Date(a.created_at))[0] || null;
const resultat = Object.assign({}, nouveau);
resultat.message_brut = nouveau.message;
resultat.message = contexte ? ((contexte.message_original || "") + "\n---\n" + nouveau.message) : nouveau.message;
resultat.demande_precedente_id = contexte ? contexte.id : null;
return [{ json: resultat }];

