const reponse = $input.first().json;
let entree;
try { entree = $('Fusionner avec le contexte précédent').item.json; } catch (e) { entree = $('Pas de contexte (nouveau client)').item.json; }
let data;
let brut = "";
try { brut = (reponse.content[0].text || "").trim(); } catch (e) { brut = ""; }
brut = brut.replace(/^```(?:json)?\s*/i, "").replace(/\s*```\s*$/i, "").trim();
try {
    data = JSON.parse(brut);
} catch (e) {
    data = null;
}
if (Array.isArray(data)) { data = data[data.length - 1]; }
if (!data) {
    data = {};
    data.type_demande = "autre";
    data.nom = entree.nom;
    data.telephone = entree.telephone;
    data.email = entree.email;
    data.vehicule = { marque: "", modele: "", annee: null, immatriculation: "" };
    data.prestation = "";
    data.motif = entree.message;
    data.urgence = "Moyenne";
    data.disponibilites_client = { moment_prefere: "indifferent", jours_a_eviter: [], delai_max_jours: null };
    data.infos_manquantes = ["analyse_impossible"];
}
if (data.demandes && Array.isArray(data.demandes) && data.demandes.length) { data = data.demandes[0]; }
data.source = entree.source;
data.canal = entree.canal;
data.source_id = entree.source_id;
data.client_existant_id = entree.client_existant_id;
if (!data.client_existant_id) {
    try {
          const clientsConnus = $('Récupérer les clients du garage').all().map(i => i.json);
          const emailIA = (data.email || "").toLowerCase().trim();
          const telIA = (data.telephone || "").replace(/\s/g, "");
          let matchIA = null;
          if (emailIA) { matchIA = clientsConnus.find(c => (c.email || "").toLowerCase().trim() === emailIA); }
          if (!matchIA && telIA) { matchIA = clientsConnus.find(c => (c.telephone || "").replace(/\s/g, "") === telIA); }
          if (matchIA) { data.client_existant_id = matchIA.id; }
    } catch (e) {}
}
data.demande_precedente_id = entree.demande_precedente_id;
data.message_original = entree.message_brut || entree.message;
data.garage_id = entree.garage_id;
data.nom = data.nom || entree.nom;
data.telephone = data.telephone || entree.telephone;
data.email = entree.email || data.email;
const doitGarderEmail = Array.isArray(data.infos_manquantes) && entree.email;
if (doitGarderEmail) { data.infos_manquantes = data.infos_manquantes.filter(k => k !== "email"); }
return [{ json: data }];

const base = $('Parser la réponse IA').item.json;
let client;
try { client = $('Mettre à jour le client').item.json; } catch (e) { client = $('Créer le client').item.json; }
return [{ json: { ...base, client_id: client.id } }];

const base = $('Parser la réponse IA').item.json;
const garage = $('Récupérer le garage (réponse)').item.json || {};
const nomGarage = String(garage.nom_garage || '').replace(/[,<>"]/g, ' ').trim();
const manquants = base.infos_manquantes || [];
const labels = { nom: "votre nom", telephone: "un numéro de téléphone", email: "votre adresse email", motif: "le motif de votre demande (quelle prestation souhaitez-vous ?)", vehicule: "les informations de votre véhicule (marque, modèle, immatriculation)", annee_vehicule: "l'année de votre véhicule", immatriculation: "l'immatriculation de votre véhicule" };
const liste = manquants.filter(k => labels[k]).map(k => labels[k]).join(", ") || "quelques informations complémentaires";

const message_reponse = `Bonjour${base.nom ? " " + base.nom : ""},\n\nMerci pour votre message. Pour traiter votre demande, pourriez-vous nous communiquer ${liste} ?\n\nMerci et à bientôt,\n${nomGarage || 'Votre garage'}`;

return [{ json: { ...base, message_reponse, nom_garage: nomGarage, garage_email: garage.email || '', automatisation_active: garage.automatisation_active === true,
  expediteur: nomGarage ? nomGarage + ' <nexorasolutions.france@gmail.com>' : '' } }];

let base;
try { base = $('Créer ou mettre à jour le véhicule').item.json; return [{ json: { ...($('Récupérer l\'id client').item.json), vehicule_id: base.id } }]; } catch (e) {
  return [{ json: { ...($('Récupérer l\'id client').item.json), vehicule_id: null } }];
}

const nouvelle = $('Récupérer l\'id véhicule (si connu)').item.json;
const recentes = $input.all().map(i => i.json);

function similarite(a, b) {
  const motsA = new Set((a || "").toLowerCase().split(/\W+/).filter(Boolean));
  const motsB = new Set((b || "").toLowerCase().split(/\W+/).filter(Boolean));
  if (motsA.size === 0 || motsB.size === 0) return 0;
  let communs = 0;
  motsA.forEach(m => { if (motsB.has(m)) communs++; });
  return communs / Math.max(motsA.size, motsB.size);
}

const DEUX_HEURES_MS = 2 * 60 * 60 * 1000;
const maintenant = Date.now();

const doublon = recentes.find(d => {
  if (d.id === nouvelle.demande_precedente_id) return false;
  const recente = d.created_at ? (maintenant - new Date(d.created_at).getTime()) < DEUX_HEURES_MS : false;
  const similaire = similarite(d.message_original, nouvelle.message_original) > 0.4;
  return recente && similaire;
});

return [{ json: { ...nouvelle, est_doublon: !!doublon, doublon_de_id: doublon ? doublon.id : null } }];

let base;
try { base = $('Finaliser la demande existante').item.json; } catch (e) { base = $('Créer la demande').item.json; }
let contexte;
try { contexte = $('Détecter un doublon').item.json; } catch (e) { contexte = $('Récupérer l\'id véhicule (si connu)').item.json; }
return [{ json: { ...contexte, demande_id: base.id } }];

const item = $('Récupérer l\'id demande').item.json;
const prestations = $input.all().map(i => i.json);
const texte = ((item.prestation || "") + " " + (item.motif || "")).toLowerCase();

let match = prestations.find(p => texte.includes((p.nom || "").toLowerCase()));

if (!match) {
  const motsClefs = [
    { mots: ["vidange"], cible: "vidange" },
    { mots: ["révision", "revision"], cible: "révision" },
    { mots: ["frein"], cible: "freins" },
    { mots: ["pneu"], cible: "pneus" },
    { mots: ["diagnostic", "panne", "voyant", "bruit"], cible: "diagnostic" },
  ];
  for (const mc of motsClefs) {
    if (mc.mots.some(m => texte.includes(m))) {
      match = prestations.find(p => (p.nom || "").toLowerCase().includes(mc.cible));
      if (match) break;
    }
  }
}

if (!match) match = prestations.find(p => (p.categorie || "").toLowerCase() === "diagnostic") || prestations[0] || null;

return [{ json: {
  ...item,
  prestation_id: match ? match.id : null,
  prestation_nom: match ? match.nom : (item.prestation || "Prestation à préciser"),
  duree_min: match ? match.duree_minutes : 60,
} }];

const item = $('Faire correspondre une prestation du catalogue').item.json;
const prestations = $('Récupérer le catalogue de prestations').all().map(i => i.json);
const prestation = prestations.find(p => p.id === item.prestation_id);
const prixHt = (prestation && prestation.prix_ht != null) ? prestation.prix_ht : null;
const montantHt = prixHt;
const montantTtc = prixHt != null ? Math.round(prixHt * 1.2 * 100) / 100 : null;

return [{ json: { ...item, montant_ht: montantHt, montant_ttc: montantTtc } }];

const HORAIRES_DEFAUT = {
  "1": [["08:30", "12:00"], ["14:00", "18:30"]],
  "2": [["08:30", "12:00"], ["14:00", "18:30"]],
  "3": [["08:30", "12:00"], ["14:00", "18:30"]],
  "4": [["08:30", "12:00"], ["14:00", "18:30"]],
  "5": [["08:30", "12:00"], ["14:00", "18:30"]],
  "6": [],
  "7": []
};

const DELAI_MINIMUM_MINUTES = 120;

const demande = $('Faire correspondre une prestation du catalogue').item.json;
const dureeMin = demande.duree_min || 60;
const dispo = demande.disponibilites_client || {};
const urgence = demande.urgence || "Moyenne";
const rdvExistants = $input.all().map(i => i.json);

let garage = {};
try { garage = $('Récupérer les horaires du garage').first().json || {}; } catch (e) { garage = {}; }

let horaires = garage.horaires;
if (typeof horaires === "string") { try { horaires = JSON.parse(horaires); } catch (e) { horaires = null; } }
if (!horaires || typeof horaires !== "object") horaires = HORAIRES_DEFAUT;

const nbMecaniciens = Number(garage.nb_mecaniciens) > 0 ? Number(garage.nb_mecaniciens) : 3;

function toMinutes(hhmm) { if (!hhmm) return 0; const [h, m] = hhmm.split(":").map(Number); return h * 60 + m; }
function momentDeLaJournee(min) { if (min < 12 * 60) return "matin"; if (min < 17 * 60) return "apres-midi"; return "soir"; }
function jourISO(d) { return d.getDay() === 0 ? 7 : d.getDay(); }

const joursNoms = ["dimanche", "lundi", "mardi", "mercredi", "jeudi", "vendredi", "samedi"];
const joursAEviter = (dispo.jours_a_eviter || []).map(j => (j || "").toLowerCase());

const maintenant = new Date();
const plancherMs = maintenant.getTime() + DELAI_MINIMUM_MINUTES * 60 * 1000;

const candidats = [];
const maxJours = dispo.delai_max_jours || 90;

for (let offset = 0; offset < maxJours + 3; offset++) {
  const date = new Date();
  date.setDate(date.getDate() + offset);
  date.setHours(0, 0, 0, 0);

  const plages = horaires[String(jourISO(date))];
  if (!Array.isArray(plages) || plages.length === 0) continue;

  const nomJour = joursNoms[date.getDay()];
  if (joursAEviter.includes(nomJour)) continue;

  const dateStr = date.toISOString().split("T")[0];
  const rdvDuJour = rdvExistants.filter(r => (r.date_debut || "").startsWith(dateStr));

  for (const plage of plages) {
    const debutPlage = toMinutes(plage[0]);
    const finPlage = toMinutes(plage[1]);
    if (!finPlage || finPlage <= debutPlage) continue;

    for (let debutMin = debutPlage; debutMin + dureeMin <= finPlage; debutMin += 30) {
      const finMin = debutMin + dureeMin;

      const debutReel = new Date(date);
      debutReel.setHours(Math.floor(debutMin / 60), debutMin % 60, 0, 0);
      if (debutReel.getTime() < plancherMs) continue;

      const chevauchements = rdvDuJour.filter(r => {
        const rDebut = toMinutes((r.date_debut || "").split("T")[1]?.slice(0, 5));
        const rFin = toMinutes((r.date_fin || "").split("T")[1]?.slice(0, 5));
        return debutMin < rFin && finMin > rDebut;
      }).length;
      if (chevauchements >= nbMecaniciens) continue;

      let score = 0;
      if (dispo.moment_prefere && dispo.moment_prefere !== "indifferent" && momentDeLaJournee(debutMin) === dispo.moment_prefere) score += 15;
      const adjacentAvant = rdvDuJour.some(r => toMinutes((r.date_fin || "").split("T")[1]?.slice(0, 5)) === debutMin);
      const adjacentApres = rdvDuJour.some(r => toMinutes((r.date_debut || "").split("T")[1]?.slice(0, 5)) === finMin);
      score += (adjacentAvant ? 6 : 0) + (adjacentApres ? 6 : 0);
      score -= offset * (urgence === "Élevée" ? 4 : 1);

      candidats.push({ dateStr, debutMin, finMin, score });
    }
  }
}

candidats.sort((a, b) => b.score - a.score);
const meilleur = candidats[0] || null;

function versISO(dateStr, minutes) {
  const h = Math.floor(minutes / 60).toString().padStart(2, "0");
  const m = (minutes % 60).toString().padStart(2, "0");
  const midi = new Date(dateStr + "T12:00:00Z");
  const paris = new Date(midi.toLocaleString("en-US", { timeZone: "Europe/Paris" }));
  const utc = new Date(midi.toLocaleString("en-US", { timeZone: "UTC" }));
  const offsetH = Math.round((paris - utc) / 3600000);
  const offsetStr = "+" + String(offsetH).padStart(2, "0") + ":00";
  return `${dateStr}T${h}:${m}:00${offsetStr}`;
}

return [{ json: {
  ...demande,
  creneau_trouve: !!meilleur,
  date_debut_proposee: meilleur ? versISO(meilleur.dateStr, meilleur.debutMin) : null,
  date_fin_proposee: meilleur ? versISO(meilleur.dateStr, meilleur.finMin) : null,
} }];

const DELAIS_MOIS = { "vidange": 12, "révision complète": 12, "contrôle technique": 24 };
const rdvItems = $('RDV entretien terminés').all().map(i => i.json);
const prestations = $input.all().map(i => i.json);
const prestationParId = Object.fromEntries(prestations.map(p => [p.id, p]));
const maintenant = Date.now();

const aRelancer = rdvItems.filter(r => {
  const prestation = prestationParId[r.prestation_id];
  const nomPrestation = (prestation?.nom || "").toLowerCase();
  const delaiMois = DELAIS_MOIS[nomPrestation] || 12;
  const dateRdv = new Date(r.date_debut).getTime();
  const moisEcoules = (maintenant - dateRdv) / (1000 * 60 * 60 * 24 * 30);
  return moisEcoules >= delaiMois;
});

return aRelancer.map(r => ({ json: r }));

const original = $('Normaliser (WhatsApp)').item.json;
const garage = $input.first() ? $input.first().json : null;
return [{ json: { ...original, garage_id: garage ? garage.id : null } }];

const items = $input.all();
return items.map((item) => {
  const expiryMs = item.json.token_expiry ? new Date(item.json.token_expiry).getTime() : 0;
  const expire = expiryMs <= Date.now() + 2 * 60 * 1000;
  return { json: { ...item.json, expire } };
});

const httpRequest = this.helpers.httpRequest;
const item = $input.first().json;
const accessToken = item.access_token;
const garageId = item.garage_id;
const connectionId = item.id;
const historyId = item.last_history_id;

if (!accessToken || !garageId) {
  return [];
}

function decodeBase64Url(data) {
  if (!data) return '';
  const b64 = data.replace(/-/g, '+').replace(/_/g, '/');
  try { return Buffer.from(b64, 'base64').toString('utf8'); } catch (e) { return ''; }
}

function extraireTexte(payload) {
  if (!payload) return '';
  if (payload.mimeType === 'text/plain' && payload.body && payload.body.data) {
    return decodeBase64Url(payload.body.data);
  }
  if (payload.parts) {
    for (const part of payload.parts) {
      const texte = extraireTexte(part);
      if (texte) return texte;
    }
  }
  if (payload.body && payload.body.data) return decodeBase64Url(payload.body.data);
  return '';
}

function header(headers, name) {
  const h = (headers || []).find((x) => x.name.toLowerCase() === name.toLowerCase());
  return h ? h.value : '';
}

// Pas encore de curseur pour cette connexion : on l'initialise et on ne traite rien ce tour-ci.
if (!historyId) {
  const profil = await httpRequest({
    method: 'GET',
    url: 'https://gmail.googleapis.com/gmail/v1/users/me/profile',
    headers: { Authorization: `Bearer ${accessToken}` },
    json: true,
  });
  return [{ json: { init_curseur: true, connection_id: connectionId, new_history_id: profil.historyId, garage_id: garageId } }];
}

let liste;
try {
  liste = await httpRequest({
    method: 'GET',
    url: `https://gmail.googleapis.com/gmail/v1/users/me/history?startHistoryId=${historyId}&historyTypes=messageAdded&maxResults=50`,
    headers: { Authorization: `Bearer ${accessToken}` },
    json: true,
  });
} catch (e) {
  return [{ json: { erreur_polling: true, detail: String(e && e.message || e), garage_id: garageId } }];
}

const messageIds = [...new Set(((liste && liste.history) || []).flatMap((h) => (h.messagesAdded || []).map((m) => m.message.id)))];
const newHistoryId = (liste && liste.historyId) || historyId;
const resultats = [];

for (const id of messageIds) {
  try {
    const detail = await httpRequest({
      method: 'GET',
      url: `https://gmail.googleapis.com/gmail/v1/users/me/messages/${id}?format=full`,
      headers: { Authorization: `Bearer ${accessToken}` },
      json: true,
    });
    const from = header(detail.payload && detail.payload.headers, 'From');
    const subject = header(detail.payload && detail.payload.headers, 'Subject');
    const text = extraireTexte(detail.payload) || detail.snippet || '';
    resultats.push({ from, subject, text, id: detail.id, garage_id: garageId, connection_id: connectionId, new_history_id: newHistoryId });
  } catch (e) {
    // un message en erreur ne doit pas bloquer les autres
  }
